CREATE TABLE chats (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE messages (id UUID PRIMARY KEY, chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_messages_chat ON messages(chat_id, created_at);
CREATE TABLE misconceptions (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id UUID REFERENCES topics(id) ON DELETE SET NULL, label VARCHAR(500) NOT NULL, occurrences INTEGER NOT NULL DEFAULT 1, resolved_at TIMESTAMPTZ);
CREATE TABLE study_plans (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, plan_date DATE NOT NULL, available_minutes INTEGER NOT NULL, readiness DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(course_id, plan_date));
CREATE TABLE study_tasks (id UUID PRIMARY KEY, plan_id UUID NOT NULL REFERENCES study_plans(id) ON DELETE CASCADE, topic_id UUID REFERENCES topics(id) ON DELETE SET NULL, title VARCHAR(500) NOT NULL, reason TEXT, duration_minutes INTEGER NOT NULL, priority DOUBLE PRECISION NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', ordinal INTEGER NOT NULL);
CREATE TABLE ai_usage (id UUID PRIMARY KEY, operation VARCHAR(100) NOT NULL, model VARCHAR(100), input_tokens INTEGER, output_tokens INTEGER, estimated_cost NUMERIC, duration_ms BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
